import UserBoxs from "../UsersBoxs/UserBoxs";
import users from "../../constants/data";

import "./DataGeneration.css";

const DataGeneration = () => {
  return (
    <div>
      {users.map((elm, index) => {
        <UserBoxs 
        key = {index}
        name = {elm.name}
        username={elm.username}
        email={elm.email}
        phone={elm.phone}
        website={elm}
        />
      })}
    </div>
  );
};

export default DataGeneration;
